-- 3. extrapolated_cells (country-level fallback)
UPDATE extrapolated_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(predicted_rev_per_firm * 0.12),
  'payroll_total',          ROUND(predicted_rev_per_firm * 0.35),
  'cost_of_goods_sold',     ROUND(predicted_rev_per_firm * 0.29),
  'utilities',              ROUND(predicted_rev_per_firm * 0.03),
  'marketing_acquisition',  ROUND(predicted_rev_per_firm * 0.02),
  'insurance_professional', ROUND(predicted_rev_per_firm * 0.04),
  'equipment_maintenance',  ROUND(predicted_rev_per_firm * 0.05),
  'regulatory_licensing',   ROUND(predicted_rev_per_firm * 0.01),
  'refreshed_at',           '2026-05-24',
  'source_note',            'Toast POS Coffee Report 2024 + Specialty Coffee Association ratios. Country-level extrapolation; coarser than regional_cells.',
  'grade',                  'D'
)
WHERE industry_id = 'cafes_coffee'
  AND predicted_rev_per_firm IS NOT NULL
  AND predicted_rev_per_firm > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));
